xml.Script:
        Colors[0] := '008000'; // Green
        Colors[1] := 'C80000'; // Red
        Colors[2] := '0000A0'; // Blue
        clYellow := 'FFFF00';
        clWhite  := 'FFFFFF';

        R  := 0.6;
        PH := 5/7; // horizontal pillow
        PV := 0.7; // vertical pillow
        H := R * 0.864; //R * sqrt(3) / 2;

        S := 3; // S segments
        // every side divided into MxN faces
        N := 8; // must be even to hide centers
        M := 9;
        MS := M * S; // FacesPerRow

        A := 2 * Pi / S;
        sa := sin(A/2);
        ca := cos(A/2);

        function QInterpolate(xi, x1, y1, x2, y2, x3, y3);
        begin
            Result :=
                y1 * (xi - x2) * (xi - x3) / (x1 - x2) / (x1 - x3) +
                y2 * (xi - x3) * (xi - x1) / (x2 - x3) / (x2 - x1) +
                y3 * (xi - x1) * (xi - x2) / (x3 - x1) / (x3 - x2);
        end;

        for i := 0 to N do begin // vertical curve
            HZ[i] := H * (-1 + 2 / N * i);
            RZ[i] := R * QInterpolate(HZ[i], -H,PV, 0,1, H,PV)
        end;

        for i := 0 to M do begin // horizontal curve
            SX[i] := sa * (-1 + 2 / M * i);
            SY[i] := QInterpolate(SX[i], -sa,ca, 0,PH, sa,ca);
        end;

        id := 0;
        for k := 0 to N do begin
            for j := 0 to S - 1 do begin
                A1 := Pi/2 + A * j;
                cA1 := cos(A1);
                sA1 := sin(A1);
                for i := 0 to M - 1 do begin
                    x[Id] := (SX[i] * cA1 + SY[i] * sA1) * RZ[k];
                    y[Id] := (SY[i] * cA1 - SX[i] * sA1) * RZ[k];
                    z[Id] := HZ[k];
                    Inc(Id);
                end;
            end;
        end;

        for i := 0 to S do begin
            ax[i] := cos(A * i);
            ay[i] := sin(A * i);
        end;
        az := sqrt(3)/2;

        D := R / sqrt(7);
        A1 := ArcCos(1 / 8);
        A2 := ArcCos(-3 / 4);

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
is := i + Seg * M;
ir := Row * MS;
i1 := is + ir;
i2 := (is + 1) mod MS + ir;
Inc(i);
